('aux-age:27-98ba2491bd','aux-age',27,'Para compartir tu calendario de Outlook con un compañero se utiliza:','["La opción Compartir calendario, eligiendo el nivel de permisos", "Una regla de reenvío automático de las convocatorias", "Las respuestas automáticas", "La firma"]'::jsonb,0,'Outlook · Calendario','Se puede permitir ver solo disponibilidad, ver detalles o editar.',null),
('aux-age:23-fc16675250','aux-age',23,'La combinación Tecla Windows + V en Windows 11 abre:','["El historial del portapapeles", "La configuración de vídeo y pantalla", "El panel de widgets con noticias y tiempo", "El Explorador de archivos"]'::jsonb,0,'Windows 11 · Portapapeles','Permite pegar elementos copiados anteriormente, si el historial está activado.',null),
